//! The line methods (`line_def`, `line_offset`, `line_crossing`,
//! `line_contains`) and `frame_grid`, checked against the C library on a
//! plain Frame and on a SkyFrame, where lines are great circles, and the
//! check that a line is used only with the kind of Frame that made it.
//!
//! `line_geometry_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/line_geometry_probe.c`, which calls the protected
//! `astLineDef`, `astLineOffset`, `astLineCrossing`, `astLineContains` and
//! `astFrameGrid` on the Frames that `frame` below builds from the same id.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "line_geometry_oracle/cases.rs"]
mod cases;

use starlink_ast::error::ErrorCode;
use starlink_ast::frames::{BasicFrameBuilder, CmpFrame, Frame, LineDef, SkyFrame};

/// The Frame a probe case id names, built as the probe builds it.
fn frame(id: &str) -> Box<dyn Frame> {
    match id {
        "basic" => Box::new(BasicFrameBuilder::new(2).build().unwrap()),
        "sky" => Box::new(SkyFrame::unset_system()),
        "sky_perm" => {
            let mut f = SkyFrame::unset_system();
            f.perm_axes(&[2, 1]).unwrap();
            Box::new(f)
        }
        "cmp" => Box::new(
            CmpFrame::new(
                Box::new(SkyFrame::unset_system()),
                Box::new(BasicFrameBuilder::new(1).build().unwrap()),
            )
            .unwrap(),
        ),
        _ => panic!("unknown frame id {id}"),
    }
}

fn line(f: &dyn Frame, seg: usize) -> Option<LineDef> {
    let [start, end] = cases::SEGMENTS[seg];
    f.line_def(&start, &end).unwrap()
}

#[test]
fn line_def_matches_the_c_library() {
    for &(id, seg, defined) in cases::LINE_DEF_CASES {
        assert_eq!(
            line(frame(id).as_ref(), seg).is_some(),
            defined,
            "{id} segment {seg}"
        );
    }
}

#[test]
fn line_offset_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(id, seg, par, prp, want) in cases::LINE_OFFSET_CASES {
        let f = frame(id);
        let got = f
            .line_offset(&line(f.as_ref(), seg).unwrap(), par, prp)
            .unwrap();
        if !crate::common::c_values_eq(&got, &want) {
            failures.push(format!(
                "{id} segment {seg} ({par}, {prp}): got {got:?}, C gives {want:?}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn line_contains_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(id, seg, point, want) in cases::LINE_CONTAINS_CASES {
        let f = frame(id);
        let got = f
            .line_contains(&line(f.as_ref(), seg).unwrap(), &point)
            .unwrap();
        if got != want {
            failures.push(format!(
                "{id} segment {seg} {point:?}: got {got}, C gives {want}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn line_crossing_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(id, s1, s2, want, want_cross, want_dist) in cases::LINE_CROSSING_CASES {
        let f = frame(id);
        let (l1, l2) = (line(f.as_ref(), s1).unwrap(), line(f.as_ref(), s2).unwrap());
        let (got, cross, dist) = f.line_crossing(&l1, &l2).unwrap();
        if got != want
            || !crate::common::c_values_eq(
                &[cross[0], cross[1], dist],
                &[want_cross[0], want_cross[1], want_dist],
            )
        {
            failures.push(format!(
                "{id} {s1} x {s2}: got ({got}, {cross:?}, {dist}), C gives ({want}, {want_cross:?}, {want_dist})"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn frame_grid_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(id, size, lbnd, ubnd, want) in cases::FRAME_GRID_CASES {
        let got = frame(id).frame_grid(size, lbnd, ubnd).unwrap();
        let points: Vec<Vec<f64>> = (0..got.npoint()).map(|i| got.point(i).to_vec()).collect();
        let same = points.len() == want.len()
            && points
                .iter()
                .zip(want)
                .all(|(g, w)| crate::common::c_values_eq(g, w));
        if !same {
            failures.push(format!(
                "{id} size {size}: got {points:?}, C gives {want:?}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn planar_frame_rejects_a_sky_line() {
    let sky = frame("sky");
    let planar = frame("basic");
    let l = line(sky.as_ref(), 0).unwrap();
    let p = line(planar.as_ref(), 6).unwrap();
    let err = planar.line_contains(&l, &[0.5, 0.0]).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Inter);
    assert!(err.message().contains(
        "astLineContains(Frame): The supplied line does not relate to the supplied Frame"
    ));
    let err = planar.line_crossing(&l, &p).unwrap_err();
    assert!(
        err.message()
            .contains("First supplied line does not relate")
    );
    let err = planar.line_crossing(&p, &l).unwrap_err();
    assert!(
        err.message()
            .contains("Second supplied line does not relate")
    );
}

#[test]
fn sky_frame_rejects_a_planar_line() {
    let sky = frame("sky");
    let planar = frame("basic");
    let l = line(planar.as_ref(), 0).unwrap();
    let err = sky.line_contains(&l, &[0.5, 0.0]).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Inter);
    assert!(err.message().contains(
        "astLineContains(SkyFrame): The supplied line does not relate to the supplied SkyFrame"
    ));
    let s = line(sky.as_ref(), 6).unwrap();
    assert_eq!(
        sky.line_crossing(&l, &s).unwrap_err().code(),
        ErrorCode::Inter
    );
    assert_eq!(
        sky.line_crossing(&s, &l).unwrap_err().code(),
        ErrorCode::Inter
    );
    assert_eq!(
        sky.line_offset(&l, 0.1, 0.0).unwrap_err().code(),
        ErrorCode::Inter
    );
}
